using AutoMapper; using Veterinaria.Datos; using Veterinaria.Entidades;
namespace Veterinaria.Negocio;
public class ReglaNegocioException(string message):Exception(message){}
public class MappingProfile:Profile { public MappingProfile(){CreateMap<Propietario,PropietarioDto>();CreateMap<PropietarioCrearDto,Propietario>();CreateMap<PropietarioActualizarDto,Propietario>();CreateMap<Mascota,MascotaDto>().ForMember(d=>d.NombrePropietario,o=>o.MapFrom(s=>s.Propietario==null?string.Empty:s.Propietario.Nombres+" "+s.Propietario.Apellidos));CreateMap<MascotaCrearDto,Mascota>();CreateMap<MascotaActualizarDto,Mascota>();} }
public interface IPropietarioServicio { Task<List<PropietarioDto>> ListarAsync();Task<PropietarioDto?> ObtenerAsync(int id);Task<List<MascotaDto>?> MascotasAsync(int id);Task<PropietarioDto> CrearAsync(PropietarioCrearDto d);Task<bool> ActualizarAsync(int id,PropietarioActualizarDto d);Task<bool> EliminarAsync(int id); }
public class PropietarioServicio(IPropietarioRepositorio r,IMascotaRepositorio m,IMapper a):IPropietarioServicio { public async Task<List<PropietarioDto>> ListarAsync()=>a.Map<List<PropietarioDto>>(await r.ListarAsync()); public async Task<PropietarioDto?> ObtenerAsync(int id){var x=await r.ObtenerAsync(id);return x==null?null:a.Map<PropietarioDto>(x);} public async Task<List<MascotaDto>?> MascotasAsync(int id){if(await r.ObtenerAsync(id)==null)return null;return a.Map<List<MascotaDto>>(await m.PorPropietarioAsync(id));} public async Task<PropietarioDto> CrearAsync(PropietarioCrearDto d){d.Dni=d.Dni.Trim();if(await r.ExisteDniAsync(d.Dni))throw new ReglaNegocioException("Ya existe un propietario con ese DNI.");var x=a.Map<Propietario>(d);await r.AgregarAsync(x);await r.GuardarAsync();return a.Map<PropietarioDto>(x);} public async Task<bool> ActualizarAsync(int id,PropietarioActualizarDto d){if(id!=d.IdPropietario)throw new ArgumentException("El identificador no coincide.");var x=await r.ObtenerAsync(id);if(x==null)return false;d.Dni=d.Dni.Trim();if(await r.ExisteDniAsync(d.Dni,id))throw new ReglaNegocioException("Ya existe un propietario con ese DNI.");a.Map(d,x);await r.GuardarAsync();return true;} public async Task<bool> EliminarAsync(int id){var x=await r.ObtenerAsync(id);if(x==null)return false;if(await r.TieneMascotasAsync(id))throw new ReglaNegocioException("No se puede eliminar un propietario con mascotas.");r.Eliminar(x);await r.GuardarAsync();return true;} }
public interface IMascotaServicio { Task<List<MascotaDto>> ListarAsync(string? e,string? n);Task<MascotaDto?> ObtenerAsync(int id);Task<MascotaDto> CrearAsync(MascotaCrearDto d);Task<bool> ActualizarAsync(int id,MascotaActualizarDto d);Task<bool> EliminarAsync(int id); }
public class MascotaServicio(IMascotaRepositorio r,IMapper a):IMascotaServicio { public async Task<List<MascotaDto>> ListarAsync(string? e,string? n)=>a.Map<List<MascotaDto>>(await r.ListarAsync(e,n)); public async Task<MascotaDto?> ObtenerAsync(int id){var x=await r.ObtenerAsync(id);return x==null?null:a.Map<MascotaDto>(x);} async Task Validar(MascotaCrearDto d){if(d.FechaNacimiento>DateOnly.FromDateTime(DateTime.Today))throw new ArgumentException("La fecha no puede ser futura.");if(!await r.PropietarioExisteAsync(d.IdPropietario))throw new ArgumentException("El propietario no existe.");} public async Task<MascotaDto> CrearAsync(MascotaCrearDto d){await Validar(d);var x=a.Map<Mascota>(d);await r.AgregarAsync(x);await r.GuardarAsync();return a.Map<MascotaDto>(x);} public async Task<bool> ActualizarAsync(int id,MascotaActualizarDto d){if(id!=d.IdMascota)throw new ArgumentException("El identificador no coincide.");var x=await r.ObtenerAsync(id);if(x==null)return false;await Validar(d);a.Map(d,x);await r.GuardarAsync();return true;} public async Task<bool> EliminarAsync(int id){var x=await r.ObtenerAsync(id);if(x==null)return false;r.Eliminar(x);await r.GuardarAsync();return true;} }
